window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ad1ddf459c96a295"]={"versions": [{"id": "FIG-ad1ddf459c96a295", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Scheduling- und Timing-Ablaufdiagramm (Gantt-artiges Zeitablaufdiagramm) im Kontext der AUTOSAR-Echtzeitanalyse (AUTOSAR_TR_TimingAnalysis). Dargestellt werden die zeitlichen Parameter, Zustandswechsel und Latenzen eines nicht-terminierenden Tasks der erweiterten Konformitätsklasse (ECC, Extended Conformance Class) unter preemptivem OS-Scheduling mit Prioritäten im AUTOSAR Classic Platform OS / OSEK-Umfeld.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Tasks unterschiedlicher statischer Priorität (<code>Task A</code> mit höchster Priorität, <code>Task B</code> mit mittlerer Priorität und <code>Task C</code> mit niedrigster Priorität auf der Ordinate <code>prio</code>) über der Zeitachse <code>t</code>. Zustände der Tasks werden durch standardisierte Balken visualisiert:</p>\n<ul class=\"fig-list\"><li>Hellgraue Balken: Zustand Ready (wartebereit / unterbrochen).\n</li><li>Dunkelgraue Balken: Zustand Running (aktive Prozessorausführung).\n</li><li>Ocker-/Goldgelbe Segmente und Markierungen: Zustand Waiting bzw. Wartezustand durch <code>WaitEvent</code>-Aufrufe.\n</li></ul>\n<p class=\"fig-p\">Explizite Markierungen / Annotationen:</p>\n<ul class=\"fig-list\"><li><code>&quot;regular&quot; WaitEvent</code>: Verweist auf ein blockierendes Warten auf ein reguläres Ereignis innerhalb des Verarbeitungszyklus.\n</li><li><code>&quot;scheduling&quot; WaitEvent</code>: Verweist auf den zyklischen Aufruf von WaitEvent am Ende eines Ausführungszyklus eines nicht-terminierenden Tasks (Warten auf das nächste Perioden-/Aktivierungsereignis).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abszisse stellt den zeitlichen Fortschritt (<code>t</code>) dar. Dargestellt ist der Ausführungsablauf von Task B in Interaktion mit Task A und Task C:</p>\n<ol class=\"fig-list\"><li>Task B wird aktivierungsbereit (Ready) und beginnt nach der initialen Verzögerung <code>IPT</code> (Initial Pending Time) mit der Ausführung (<code>CET1</code>).\n</li><li>Task B führt ein reguläres <code>WaitEvent</code> aus, wechselt in den Wartezustand (Waiting, ockerfarbener Block) und gibt den Prozessor frei.\n</li><li>Nach Eintritt des Ereignisses wird Task B wieder Ready und setzt nach Scheduling-Latenzen die Ausführung fort (<code>CET2</code>), wird zwischenzeitlich durch Präemption (<code>PRE</code>) unterbrochen und beendet seinen Berechnungsabschnitt mit <code>CET3</code>.\n</li><li>Die kumulierte reine Ausführungszeit ergibt sich aus CET = CET1 + CET2 + CET3.\n</li><li>Am Zyklusende setzt Task B ein <code>&quot;scheduling&quot; WaitEvent</code> ab und verweilt bis zum nächsten Zyklusbeginn im Zustand Waiting (repräsentiert durch das lange goldgelbe Band).\n</li><li>Zeitmetriken für Task B:\n<ul class=\"fig-list\"><li><code>IPT</code>: Initial Pending Time (Aktivierung bis zum ersten Rechenstart).\n</li><li><code>CET</code> (CET1, CET2, CET3): Core Execution Time / reine Rechenzeitabschnitte.\n</li><li><code>PRE</code>: Preemption Time (Unterbrechung durch höherpriore Aktivität).\n</li><li><code>GET</code>: Gross Execution Time (Zeitspanne vom ersten Rechenbeginn bis zum Abschluss der Berechnung vor dem Schlafenlegen).\n</li><li><code>RT</code>: Response Time (Gesamtdauer von Aktivierungsereignis bis Berechnungsende).\n</li><li><code>DL</code>: Deadline (relative Frist ab Aktivierung).\n</li><li><code>NST1</code>, <code>NST2</code>: Non-Scheduling Times (Phasen, in denen der Task nicht aktiv/bereit ist, z. B. im Schlaffustand). Gesamte Non-Scheduling Time: NST = NST1 + NST2.\n</li><li><code>ST</code>: Suspension Time (Gesamtzeit im Wartezustand vor dem nächsten Zyklus).\n</li><li><code>PER</code>: Period (Periode zwischen Aktivierungsflanken/Ereignissen).\n</li><li><code>DT</code>: Distance Time (zeitlicher Abstand zwischen aufeinanderfolgenden Startpunkten der Task-Ausführung).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der formalen Begriffsbestimmung und Parametrisierung im Timing Model (TIMEX) von AUTOSAR für nicht-terminierende Tasks (ECC). Es definiert die Zuordnung von Timing-Attributen (wie Core Execution Time, Gross Execution Time, Response Time, Non-Scheduling Time, Period und Deadline) auf Tasks, die ihre Ausführung nicht über <code>TerminateTask()</code> beenden, sondern zyklisch über <code>WaitEvent()</code> auf den nächsten Reaktivierungszeitpunkt warten. Entwickler müssen bei der Timing-Modellierung und Worst-Case Execution Time (WCET) / Schichtenanalyse beachten, dass Wartezeiten (<code>WaitEvent</code>) differenziert zu betrachten sind: Reguläre Wartezustände innerhalb der Arbeitslogik zählen zur Bruttoausführungszeit/Response Time, während Scheduling-Wartezustände am Zyklusende die Periodendauer und Non-Scheduling Times aufspannen.</p>"}, {"id": "FIG-42daf1c10a90dfdf", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Scheduling- und Timing-Ablaufdiagramm (Gantt-artiges Zeitablaufdiagramm) im Kontext der AUTOSAR-Echtzeitanalyse (AUTOSAR_TR_TimingAnalysis). Dargestellt werden die zeitlichen Parameter, Zustandswechsel und Latenzen eines nicht-terminierenden Tasks der erweiterten Konformitätsklasse (ECC, Extended Conformance Class) unter preemptivem OS-Scheduling mit Prioritäten im AUTOSAR Classic Platform OS / OSEK-Umfeld.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Tasks unterschiedlicher statischer Priorität (<code>Task A</code> mit höchster Priorität, <code>Task B</code> mit mittlerer Priorität und <code>Task C</code> mit niedrigster Priorität auf der Ordinate <code>prio</code>) über der Zeitachse <code>t</code>. Zustände der Tasks werden durch standardisierte Balken visualisiert:</p>\n<ul class=\"fig-list\"><li>Hellgraue Balken: Zustand Ready (wartebereit / unterbrochen).\n</li><li>Dunkelgraue Balken: Zustand Running (aktive Prozessorausführung).\n</li><li>Ocker-/Goldgelbe Segmente und Markierungen: Zustand Waiting bzw. Wartezustand durch <code>WaitEvent</code>-Aufrufe.\n</li></ul>\n<p class=\"fig-p\">Explizite Markierungen / Annotationen:</p>\n<ul class=\"fig-list\"><li><code>&quot;regular&quot; WaitEvent</code>: Verweist auf ein blockierendes Warten auf ein reguläres Ereignis innerhalb des Verarbeitungszyklus.\n</li><li><code>&quot;scheduling&quot; WaitEvent</code>: Verweist auf den zyklischen Aufruf von WaitEvent am Ende eines Ausführungszyklus eines nicht-terminierenden Tasks (Warten auf das nächste Perioden-/Aktivierungsereignis).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abszisse stellt den zeitlichen Fortschritt (<code>t</code>) dar. Dargestellt ist der Ausführungsablauf von Task B in Interaktion mit Task A und Task C:</p>\n<ol class=\"fig-list\"><li>Task B wird aktivierungsbereit (Ready) und beginnt nach der initialen Verzögerung <code>IPT</code> (Initial Pending Time) mit der Ausführung (<code>CET1</code>).\n</li><li>Task B führt ein reguläres <code>WaitEvent</code> aus, wechselt in den Wartezustand (Waiting, ockerfarbener Block) und gibt den Prozessor frei.\n</li><li>Nach Eintritt des Ereignisses wird Task B wieder Ready und setzt nach Scheduling-Latenzen die Ausführung fort (<code>CET2</code>), wird zwischenzeitlich durch Präemption (<code>PRE</code>) unterbrochen und beendet seinen Berechnungsabschnitt mit <code>CET3</code>.\n</li><li>Die kumulierte reine Ausführungszeit ergibt sich aus CET = CET1 + CET2 + CET3.\n</li><li>Am Zyklusende setzt Task B ein <code>&quot;scheduling&quot; WaitEvent</code> ab und verweilt bis zum nächsten Zyklusbeginn im Zustand Waiting (repräsentiert durch das lange goldgelbe Band).\n</li><li>Zeitmetriken für Task B:\n<ul class=\"fig-list\"><li><code>IPT</code>: Initial Pending Time (Aktivierung bis zum ersten Rechenstart).\n</li><li><code>CET</code> (CET1, CET2, CET3): Core Execution Time / reine Rechenzeitabschnitte.\n</li><li><code>PRE</code>: Preemption Time (Unterbrechung durch höherpriore Aktivität).\n</li><li><code>GET</code>: Gross Execution Time (Zeitspanne vom ersten Rechenbeginn bis zum Abschluss der Berechnung vor dem Schlafenlegen).\n</li><li><code>RT</code>: Response Time (Gesamtdauer von Aktivierungsereignis bis Berechnungsende).\n</li><li><code>DL</code>: Deadline (relative Frist ab Aktivierung).\n</li><li><code>NST1</code>, <code>NST2</code>: Non-Scheduling Times (Phasen, in denen der Task nicht aktiv/bereit ist, z. B. im Schlaffustand). Gesamte Non-Scheduling Time: NST = NST1 + NST2.\n</li><li><code>ST</code>: Suspension Time (Gesamtzeit im Wartezustand vor dem nächsten Zyklus).\n</li><li><code>PER</code>: Period (Periode zwischen Aktivierungsflanken/Ereignissen).\n</li><li><code>DT</code>: Distance Time (zeitlicher Abstand zwischen aufeinanderfolgenden Startpunkten der Task-Ausführung).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der formalen Begriffsbestimmung und Parametrisierung im Timing Model (TIMEX) von AUTOSAR für nicht-terminierende Tasks (ECC). Es definiert die Zuordnung von Timing-Attributen (wie Core Execution Time, Gross Execution Time, Response Time, Non-Scheduling Time, Period und Deadline) auf Tasks, die ihre Ausführung nicht über <code>TerminateTask()</code> beenden, sondern zyklisch über <code>WaitEvent()</code> auf den nächsten Reaktivierungszeitpunkt warten. Entwickler müssen bei der Timing-Modellierung und Worst-Case Execution Time (WCET) / Schichtenanalyse beachten, dass Wartezeiten (<code>WaitEvent</code>) differenziert zu betrachten sind: Reguläre Wartezustände innerhalb der Arbeitslogik zählen zur Bruttoausführungszeit/Response Time, während Scheduling-Wartezustände am Zyklusende die Periodendauer und Non-Scheduling Times aufspannen.</p>"}], "trans": [{"from": "FIG-ad1ddf459c96a295", "to": "FIG-42daf1c10a90dfdf", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
